coding.solution:
import re

def compile_count(script, values):
    texts = set()
    for v in values:
        texts.add(re.sub(r'\$\{(\w+)\}', lambda m: v.get(m.group(1), m.group(0)), script))
    return len(texts)

def uses_interpolation(script):
    return '${' in script
